// ATOM2_03 · Selecionar lote: empresas validadas, sem opt-out. Padrão: só F1. Com company_ids: reprocessa as indicadas (mesmo em F2).
// Falhas anteriores só voltam com reprocessar_falhas.
const p = $('Parâmetros').first().json;
const limite = Math.max(1, Math.min(50, Number(p.limite) || 15));
const ids = String(p.company_ids || '').split(',').map((s) => s.trim()).filter(Boolean);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.company_id && r.dominio);
return rows
  .filter((r) => r.opt_out !== true && String(r.opt_out) !== 'true')
  .filter((r) => (ids.length ? ids.includes(r.company_id) : r.funil_etapa === 'F1'))
  .filter((r) => ids.length || p.reprocessar_falhas === true || !/^N1 falhou/.test(String(r.status_motivo || '')))
  .sort((a, b) => String(a.criado_em || '').localeCompare(String(b.criado_em || '')) || a.company_id.localeCompare(b.company_id))
  .slice(0, limite)
  .map((r) => ({ json: r }));

// ATOM2_03 · W03_N1_CRAWL · Rastrear site (Code node, "Run Once for All Items").
// Fonte: Playbook Operacional §4 (A, B, C) e spec 01 §3. Edite aqui e recole no nó.
// Entrada: itens de atom2_empresas (funil_etapa F1, com dominio). Saída: 1 item por empresa com o rastreio bruto.
// Só faz GET em páginas públicas: respeita robots.txt, não envia formulários, não contorna bloqueios.
// URL mínima: o Code node do n8n Cloud não expõe o global URL (verificado em 09/10/2026, execução 3541).
// Resolve relativo/absoluto e normaliza ./ e ../; suficiente para http(s), tel:, mailto:.
class URLMin {
  constructor(ref, base) {
    ref = String(ref ?? '').trim();
    const ABS = /^([a-z][a-z0-9+.-]*:)\/\/(?:([^:@\/?#]*)(?::([^@\/?#]*))?@)?(\[[^\]]+\]|[^:\/?#]*)(?::(\d*))?([^?#]*)(\?[^#]*)?(#.*)?$/i;
    let m = ABS.exec(ref);
    if (!m && /^[a-z][a-z0-9+.-]*:/i.test(ref)) {
      const p = /^([a-z][a-z0-9+.-]*:)(.*)$/i.exec(ref);
      Object.assign(this, { protocol: p[1].toLowerCase(), username: '', password: '', hostname: '', port: '', pathname: p[2], search: '', hash: '' });
      return;
    }
    if (!m) {
      if (base === undefined) throw new TypeError('URL inválida: ' + ref);
      const b = base instanceof URLMin ? base : new URLMin(base);
      const origem = b.protocol + '//' + (b.username ? b.username + (b.password ? ':' + b.password : '') + '@' : '') + b.hostname + (b.port ? ':' + b.port : '');
      let abs;
      if (ref.startsWith('//')) abs = b.protocol + ref;
      else if (ref.startsWith('/')) abs = origem + ref;
      else if (ref.startsWith('?')) abs = origem + b.pathname + ref;
      else if (ref.startsWith('#') || ref === '') abs = origem + b.pathname + b.search + ref;
      else abs = origem + b.pathname.replace(/[^/]*$/, '') + ref;
      m = ABS.exec(abs);
      if (!m) throw new TypeError('URL inválida: ' + ref);
    }
    const partes = [];
    for (const s of (m[6] || '/').split('/').slice(1)) {
      if (s === '..') partes.pop();
      else if (s !== '.') partes.push(s);
    }
    const ultimo = (m[6] || '/').split('/').pop();
    Object.assign(this, {
      protocol: m[1].toLowerCase(), username: m[2] || '', password: m[3] || '', hostname: (m[4] || '').toLowerCase(), port: m[5] || '',
      pathname: '/' + partes.join('/') + (ultimo === '.' || ultimo === '..' ? '/' : ''), search: m[7] && m[7] !== '?' ? m[7] : '', hash: m[8] && m[8] !== '#' ? m[8] : ''
    });
    if (!this.hostname) throw new TypeError('URL sem host: ' + ref);
    if ((this.protocol === 'https:' && this.port === '443') || (this.protocol === 'http:' && this.port === '80')) this.port = '';
  }
  toString() {
    if (!this.hostname) return this.protocol + this.pathname;
    return this.protocol + '//' + (this.username ? this.username + (this.password ? ':' + this.password : '') + '@' : '') + this.hostname + (this.port ? ':' + this.port : '') + this.pathname + this.search + this.hash;
  }
}
const URL_ = typeof URL === 'function' ? URL : URLMin;

const http = this.helpers.httpRequest.bind(this.helpers);
const empresas = $input.all().map((i) => i.json).filter((e) => e && e.company_id && e.dominio);

const UA = 'AtomDigitalN1/1.0 (+https://atomdigital.com.br; diagnostico publico)';
const TIMEOUT_MS = 15000, MAX_REDIRECTS = 5, MAX_HTML = 2000000, MAX_EXTRAS = 5, PAUSA_MS = 700;
// Contato e "sobre" só como segmento inteiro do caminho ou texto exato do link ("lentes-de-contato" e "protese-sobre-implantes" não contam).
const GRUPOS = [
  ['agendamento', (c, t) => /agend|marcar|marque|consulta-online|reserv|booking/.test(c + ' ' + t)],
  ['contato', (c, t) => /\/(contato|contatos|fale-conosco|faleconosco|contact|contact-us|atendimento)(\/|\.|$)/.test(c) || /^(contato|fale conosco|contact)$/.test(t)],
  ['servicos', (c, t) => /tratamento|servico|especialidade|procedimento|exame|odontologia-|implante|ortodont/.test(c + ' ' + t)],
  ['sobre', (c, t) => /\/(sobre|sobre-nos|quem-somos|equipe|corpo-clinico|institucional|nossa-clinica|a-clinica)(\/|\.|$)/.test(c) || /^(sobre|sobre nos|quem somos|equipe|a clinica)$/.test(t)],
  ['local', (c, t) => /unidade|localiza|onde-estamos|endereco|como-chegar/.test(c + ' ' + t)]
];

const texto = (v) => (v === null || v === undefined ? '' : String(v).trim());
const dormir = (ms) => new Promise((r) => setTimeout(r, ms));
const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();

// Anti-SSRF sem DNS (Code node não resolve DNS): só http(s), porta padrão, host público por nome.
function urlSegura(u) {
  let p;
  try { p = new URL_(u); } catch (e) { return false; }
  if (!['http:', 'https:'].includes(p.protocol) || p.username || p.password) return false;
  if (p.port && !['80', '443'].includes(p.port)) return false;
  const h = p.hostname.toLowerCase();
  if (/^\d+(\.\d+){3}$/.test(h) || h.includes(':') || h.startsWith('[')) return false;
  if (h === 'localhost' || /\.(local|internal|localhost|lan|home|corp|intranet)$/.test(h)) return false;
  return /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(h);
}
const mesmoSite = (u, dominio) => {
  try { const h = new URL_(u).hostname.toLowerCase().replace(/^www\./, ''); return h === dominio || h.endsWith('.' + dominio); } catch (e) { return false; }
};

async function buscar(url) {
  const saltos = [];
  let atual = url;
  for (let i = 0; i <= MAX_REDIRECTS; i++) {
    if (!urlSegura(atual)) return { url, url_final: atual, status: 0, saltos, erro: 'url_bloqueada' };
    let r;
    try {
      r = await http({ method: 'GET', url: atual, headers: { 'User-Agent': UA, Accept: 'text/html,application/xhtml+xml,text/plain,application/xml;q=0.9,*/*;q=0.5' }, timeout: TIMEOUT_MS, returnFullResponse: true, disableFollowRedirect: true, ignoreHttpStatusErrors: true, encoding: 'text' });
    } catch (e) {
      const msg = texto(e && (e.code || e.message)).slice(0, 120);
      return { url, url_final: atual, status: 0, saltos, erro: /timeout|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(msg) ? 'timeout' : 'falha_rede: ' + msg };
    }
    const status = Number(r.statusCode || 0);
    const hdr = {};
    for (const [k, v] of Object.entries(r.headers || {})) hdr[k.toLowerCase()] = Array.isArray(v) ? v.join(', ') : texto(v);
    if (status >= 300 && status < 400 && hdr.location) {
      const prox = new URL_(hdr.location, atual).toString();
      saltos.push({ de: atual, para: prox, status });
      atual = prox;
      continue;
    }
    const corpo = typeof r.body === 'string' ? r.body : r.body ? JSON.stringify(r.body) : '';
    return { url, url_final: atual, status, saltos, content_type: hdr['content-type'] || '', x_robots_tag: hdr['x-robots-tag'] || '', corpo: corpo.slice(0, MAX_HTML), truncado: corpo.length > MAX_HTML, erro: status === 429 ? 'limite_429' : null };
  }
  return { url, url_final: atual, status: 0, saltos, erro: 'redirecionamentos_demais' };
}

// robots.txt simplificado: grupos "User-agent: *" (e o nosso), Disallow/Allow por prefixo, Sitemap.
function lerRobots(txt) {
  const regras = [], sitemaps = [];
  let aplica = false, emGrupo = false;
  for (const linha of String(txt || '').split(/\r?\n/)) {
    const l = linha.replace(/#.*/, '').trim();
    const m = /^([a-z-]+)\s*:\s*(.*)$/i.exec(l);
    if (!m) continue;
    const campo = m[1].toLowerCase(), valor = m[2].trim();
    if (campo === 'sitemap') { if (valor) sitemaps.push(valor); continue; }
    if (campo === 'user-agent') {
      if (!emGrupo) aplica = false;
      emGrupo = true;
      if (valor === '*' || /atomdigitaln1/i.test(valor)) aplica = true;
      continue;
    }
    emGrupo = false;
    if (aplica && (campo === 'disallow' || campo === 'allow')) regras.push({ tipo: campo, caminho: valor });
  }
  const permitido = (caminho) => {
    let melhor = null;
    for (const r of regras) {
      if (!r.caminho) continue;
      const pref = r.caminho.replace(/\*.*$/, '').replace(/\$$/, '');
      if (caminho.startsWith(pref) && (!melhor || pref.length > melhor.pref.length || (pref.length === melhor.pref.length && r.tipo === 'allow'))) melhor = { pref, tipo: r.tipo };
    }
    return !melhor || melhor.tipo === 'allow';
  };
  return { regras, sitemaps, permitido, bloqueia_tudo: !permitido('/') };
}

function escolherExtras(html, base, dominio, permitido) {
  const vistos = new Set(), porGrupo = {};
  const re = /<a\b[^>]*href\s*=\s*["']([^"'#]+)[^"']*["'][^>]*>([\s\S]*?)<\/a\s*>/gi;
  let m;
  while ((m = re.exec(html))) {
    let u;
    try { u = new URL_(m[1].trim(), base); } catch (e) { continue; }
    if (!['http:', 'https:'].includes(u.protocol) || !mesmoSite(u.toString(), dominio)) continue;
    u.hash = '';
    const chave = u.pathname.replace(/\/$/, '') || '/';
    if (chave === '/' || vistos.has(chave) || /\.(pdf|jpe?g|png|gif|webp|svg|zip|mp4)$/i.test(chave)) continue;
    vistos.add(chave);
    if (!permitido(u.pathname)) continue;
    const caminho = semAcento(u.pathname), rotulo = semAcento(m[2].replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
    for (const [g, testa] of GRUPOS) if (!porGrupo[g] && testa(caminho, rotulo)) { porGrupo[g] = u.toString(); break; }
  }
  return GRUPOS.map(([g]) => porGrupo[g] && { grupo: g, url: porGrupo[g] }).filter(Boolean).slice(0, MAX_EXTRAS);
}

const saida = [];
for (const e of empresas) {
  const observado = new Date().toISOString();
  const dominio = texto(e.dominio).toLowerCase();
  const reg = { company_id: e.company_id, empresa: e, dominio, observado_em: observado, robots: null, sitemap: null, http_inseguro: null, paginas: [], limitacoes: [], falha: null };
  const base = 'https://' + dominio + '/';

  const rb = await buscar(base + 'robots.txt');
  const robots = rb.status === 200 && !/html/i.test(rb.content_type) ? lerRobots(rb.corpo) : lerRobots('');
  reg.robots = { url: base + 'robots.txt', status: rb.status, erro: rb.erro, encontrado: rb.status === 200 && !/html/i.test(rb.content_type), bloqueia_tudo: robots.bloqueia_tudo, sitemaps: robots.sitemaps };
  if (robots.bloqueia_tudo) {
    reg.limitacoes.push('robots.txt bloqueia o rastreio de todo o site; nada além do robots.txt foi lido');
    reg.falha = 'robots_bloqueia';
    saida.push({ json: reg });
    continue;
  }
  await dormir(PAUSA_MS);

  let home = await buscar(base);
  if (home.status === 0 && /ENOTFOUND/.test(home.erro || '') && !dominio.startsWith('www.')) {
    await dormir(PAUSA_MS);
    const www = await buscar('https://www.' + dominio + '/');
    if (www.status) { home = www; reg.limitacoes.push('o domínio sem www não resolve; a home foi lida em www.' + dominio); }
  }
  if (home.status === 0 && /^(timeout|falha_rede)/.test(home.erro || '')) {
    await dormir(PAUSA_MS);
    const alt = await buscar('http://' + dominio + '/');
    if (alt.status) { home = alt; reg.limitacoes.push('HTTPS não respondeu; a home foi lida por HTTP'); }
  }
  reg.paginas.push({ grupo: 'home', ...home });
  if (home.erro === 'limite_429') { reg.falha = 'limite_429'; reg.limitacoes.push('o site respondeu 429 (limite de acessos); rastreio interrompido para tentar depois'); saida.push({ json: reg }); continue; }
  if (home.status !== 200 || !/html/i.test(home.content_type || '')) {
    reg.falha = home.status === 0 ? (home.erro || 'sem_resposta') : 'home_status_' + home.status;
    reg.limitacoes.push('a página inicial não pôde ser lida (' + reg.falha + ')');
    saida.push({ json: reg });
    continue;
  }
  if (home.truncado) reg.limitacoes.push('HTML da home maior que ' + MAX_HTML + ' caracteres; analisado só o início');
  // Daqui em diante usa o host que de fato respondeu (pode ser www.).
  const hostLido = (/^https?:\/\/([^/:?#]+)/i.exec(home.url_final) || [, dominio])[1].toLowerCase();
  const origemLida = home.url_final.replace(/^(https?:\/\/[^/?#]+).*$/i, '$1') + '/';

  // A. A versão http:// redireciona para https://?
  if (/^https:/.test(home.url_final)) {
    await dormir(PAUSA_MS);
    const h = await buscar('http://' + hostLido + '/');
    reg.http_inseguro = { url: 'http://' + hostLido + '/', status: h.status, url_final: h.url_final, saltos: h.saltos, vai_para_https: /^https:/.test(h.url_final), erro: h.erro };
  }

  // B. Sitemap: o do robots.txt ou /sitemap.xml.
  const smUrl = robots.sitemaps.find((s) => urlSegura(s) && mesmoSite(s, dominio)) || origemLida + 'sitemap.xml';
  await dormir(PAUSA_MS);
  const sm = await buscar(smUrl);
  reg.sitemap = { url: smUrl, origem: robots.sitemaps.length ? 'robots.txt' : 'padrao', status: sm.status, encontrado: sm.status === 200 && /<(urlset|sitemapindex)\b/i.test(sm.corpo || ''), erro: sm.erro };

  // C. Até 5 URLs estratégicas ligadas a partir da home.
  for (const x of escolherExtras(home.corpo, home.url_final, dominio, robots.permitido)) {
    await dormir(PAUSA_MS);
    const p = await buscar(x.url);
    reg.paginas.push({ grupo: x.grupo, ...p });
    if (p.erro === 'limite_429') { reg.limitacoes.push('429 ao ler páginas internas; rastreio parcial'); break; }
  }
  reg.limitacoes.push('PageSpeed/Lighthouse não executado neste rastreio: nenhum número de velocidade é reportado');
  saida.push({ json: reg });
}
return saida;

// ATOM2_03 · W04_N1_ANALYZE · Achados N1 (Code node, "Run Once for All Items").
// Fonte: Playbook Operacional §4 (A–J) e spec 01 §2.3. Edite aqui e recole no nó.
// Entrada: itens do W03 (rastreio bruto). Saída: 1 item por empresa { company_id, empresa, auditoria, achados[] }.
// Regras: só afirma o que está no HTML lido; cada achado tem URL, data, método, evidência e confiança.
// GEO é prontidão, nunca prova de citação. Não infere posição em mapas, velocidade nem taxa de conversão.
// URL mínima: o Code node do n8n Cloud não expõe o global URL (verificado em 09/10/2026, execução 3541).
// Resolve relativo/absoluto e normaliza ./ e ../; suficiente para http(s), tel:, mailto:.
class URLMin {
  constructor(ref, base) {
    ref = String(ref ?? '').trim();
    const ABS = /^([a-z][a-z0-9+.-]*:)\/\/(?:([^:@\/?#]*)(?::([^@\/?#]*))?@)?(\[[^\]]+\]|[^:\/?#]*)(?::(\d*))?([^?#]*)(\?[^#]*)?(#.*)?$/i;
    let m = ABS.exec(ref);
    if (!m && /^[a-z][a-z0-9+.-]*:/i.test(ref)) {
      const p = /^([a-z][a-z0-9+.-]*:)(.*)$/i.exec(ref);
      Object.assign(this, { protocol: p[1].toLowerCase(), username: '', password: '', hostname: '', port: '', pathname: p[2], search: '', hash: '' });
      return;
    }
    if (!m) {
      if (base === undefined) throw new TypeError('URL inválida: ' + ref);
      const b = base instanceof URLMin ? base : new URLMin(base);
      const origem = b.protocol + '//' + (b.username ? b.username + (b.password ? ':' + b.password : '') + '@' : '') + b.hostname + (b.port ? ':' + b.port : '');
      let abs;
      if (ref.startsWith('//')) abs = b.protocol + ref;
      else if (ref.startsWith('/')) abs = origem + ref;
      else if (ref.startsWith('?')) abs = origem + b.pathname + ref;
      else if (ref.startsWith('#') || ref === '') abs = origem + b.pathname + b.search + ref;
      else abs = origem + b.pathname.replace(/[^/]*$/, '') + ref;
      m = ABS.exec(abs);
      if (!m) throw new TypeError('URL inválida: ' + ref);
    }
    const partes = [];
    for (const s of (m[6] || '/').split('/').slice(1)) {
      if (s === '..') partes.pop();
      else if (s !== '.') partes.push(s);
    }
    const ultimo = (m[6] || '/').split('/').pop();
    Object.assign(this, {
      protocol: m[1].toLowerCase(), username: m[2] || '', password: m[3] || '', hostname: (m[4] || '').toLowerCase(), port: m[5] || '',
      pathname: '/' + partes.join('/') + (ultimo === '.' || ultimo === '..' ? '/' : ''), search: m[7] && m[7] !== '?' ? m[7] : '', hash: m[8] && m[8] !== '#' ? m[8] : ''
    });
    if (!this.hostname) throw new TypeError('URL sem host: ' + ref);
    if ((this.protocol === 'https:' && this.port === '443') || (this.protocol === 'http:' && this.port === '80')) this.port = '';
  }
  toString() {
    if (!this.hostname) return this.protocol + this.pathname;
    return this.protocol + '//' + (this.username ? this.username + (this.password ? ':' + this.password : '') + '@' : '') + this.hostname + (this.port ? ':' + this.port : '') + this.pathname + this.search + this.hash;
  }
}
const URL_ = typeof URL === 'function' ? URL : URLMin;

const ANALISADOR_VERSAO = 'n1_v1';
const SEV_PESO = { alta: 3, media: 2, baixa: 1 };
const CONF_MIN_ABORDAGEM = 0.8;

const texto = (v) => (v === null || v === undefined ? '' : String(v).trim());
const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
function hash(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}
const decodificar = (s) => String(s || '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
const recorte = (s, n = 160) => { const t = decodificar(s).replace(/\s+/g, ' ').trim(); return t.length > n ? t.slice(0, n - 1) + '…' : t; };

function lerHtml(html) {
  const h = String(html || '');
  const semScripts = h.replace(/<!--[\s\S]*?-->/g, ' ').replace(/<(script|style|noscript|template|svg)\b[\s\S]*?<\/\1>/gi, ' ');
  const head = (/<head\b[\s\S]*?<\/head>/i.exec(h) || [''])[0];
  const meta = (nome) => {
    const re = new RegExp('<meta\\b[^>]*(?:name|property)\\s*=\\s*["\']' + nome + '["\'][^>]*>', 'i');
    const tag = (re.exec(h) || [''])[0];
    const c = /content\s*=\s*["']([^"']*)["']/i.exec(tag);
    return tag ? { tag: recorte(tag, 200), valor: c ? decodificar(c[1]).trim() : '' } : null;
  };
  const titulos = (n) => [...semScripts.matchAll(new RegExp('<h' + n + '\\b[^>]*>([\\s\\S]*?)<\\/h' + n + '>', 'gi'))].map((m) => recorte(m[1].replace(/<[^>]+>/g, ' '), 120)).filter(Boolean);
  // </a > com espaços existe em sites reais (execução 3543, Barsotini): aceitar \s* antes do >.
  const links = [...h.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a\s*>/gi)].map((m) => {
    const href = (/href\s*=\s*["']([^"']*)["']/i.exec(m[1]) || [])[1] || '';
    return { href: decodificar(href).trim(), texto: recorte(m[2].replace(/<[^>]+>/g, ' '), 80), tag: recorte(m[0], 200) };
  });
  const botoes = [...h.matchAll(/<button\b[^>]*>([\s\S]*?)<\/button\s*>/gi)].map((m) => ({ texto: recorte(m[1].replace(/<[^>]+>/g, ' '), 80), tag: recorte(m[0], 200) }));
  const ldjson = [...h.matchAll(/<script\b[^>]*type\s*=\s*["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)].map((m) => m[1].trim());
  const corpoTexto = decodificar(((/<body\b[\s\S]*$/i.exec(semScripts) || [semScripts])[0]).replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
  const canonicalTag = (/<link\b[^>]*rel\s*=\s*["']canonical["'][^>]*>/i.exec(h) || [''])[0];
  return {
    title: (() => { const m = /<title\b[^>]*>([\s\S]*?)<\/title>/i.exec(head || h); return m ? recorte(m[1], 200) : null; })(),
    description: meta('description'), robots: meta('robots'), viewport: meta('viewport'),
    canonical: canonicalTag ? { tag: recorte(canonicalTag, 200), href: ((/href\s*=\s*["']([^"']*)["']/i.exec(canonicalTag) || [])[1] || '').trim() } : null,
    h1: titulos(1), h2: titulos(2), h3: titulos(3), links, botoes, ldjson,
    formularios: (h.match(/<form\b/gi) || []).length,
    iframes: [...h.matchAll(/<iframe\b[^>]*src\s*=\s*["']([^"']+)["']/gi)].map((m) => m[1]),
    texto: corpoTexto, palavras: corpoTexto ? corpoTexto.split(' ').length : 0,
    spa: /<div[^>]+id\s*=\s*["'](root|app|__next|__nuxt)["'][^>]*>\s*<\/div>/i.test(h) || /window\.__NUXT__|data-reactroot|ng-version/i.test(h)
  };
}

function tiposSchema(blocos) {
  const tipos = [], erros = [];
  const coletar = (o) => {
    if (!o || typeof o !== 'object') return;
    if (Array.isArray(o)) return o.forEach(coletar);
    const t = o['@type'];
    if (t) (Array.isArray(t) ? t : [t]).forEach((x) => tipos.push(String(x)));
    if (o['@graph']) coletar(o['@graph']);
  };
  for (const b of blocos) {
    try { coletar(JSON.parse(b)); } catch (e) { erros.push(recorte(b, 120)); }
  }
  return { tipos: [...new Set(tipos)], erros };
}

const RX = {
  agendamento: /agend|marcar|marque|agende|consulta online|reserv|book/,
  whatsapp: /wa\.me\/|api\.whatsapp\.com|web\.whatsapp\.com|whatsapp:\/\//i,
