const TIPOS_LOCAIS = /^(LocalBusiness|Dentist|MedicalClinic|MedicalBusiness|MedicalOrganization|Physician|Hospital|Organization|HealthAndBeautyBusiness|AutoPartsStore|TireShop|Store)$/i;

function analisar(reg) {
  const e = reg.empresa || {};
  const observado = reg.observado_em;
  const auditId = 'a_' + hash(reg.company_id + '|' + observado.slice(0, 10) + '|' + ANALISADOR_VERSAO);
  const paginasOk = (reg.paginas || []).filter((p) => p.status === 200 && /html/i.test(p.content_type || '') && p.corpo);
  const auditoria = {
    audit_id: auditId, company_id: reg.company_id, versao: ANALISADOR_VERSAO, observado_em: observado,
    urls: (reg.paginas || []).map((p) => ({ grupo: p.grupo, url: p.url, url_final: p.url_final, status: p.status, erro: p.erro || null })),
    limitacoes: [...(reg.limitacoes || [])], status: 'concluido', falha: reg.falha || null,
    principal_finding_id: null, resumo_finding_ids: []
  };
  const achados = [];
  if (reg.falha || !paginasOk.length) {
    auditoria.status = 'falha';
    auditoria.falha = reg.falha || 'nenhuma_pagina_lida';
    return { auditoria, achados };
  }
  const home = paginasOk.find((p) => p.grupo === 'home') || paginasOk[0];
  const H = lerHtml(home.corpo);
  const todas = paginasOk.map((p) => ({ p, d: p === home ? H : lerHtml(p.corpo) }));
  const urlHome = home.url_final;
  if (H.spa && H.palavras < 80) auditoria.limitacoes.push('conteúdo da home parece renderizado por JavaScript; achados de conteúdo, títulos e CTAs foram suprimidos para não afirmar ausência falsa');
  if (home.truncado) auditoria.limitacoes.push('HTML da home foi cortado no limite de leitura; achados de ausência (conteúdo, contato, CTA) foram suprimidos');
  const conteudoConfiavel = !(H.spa && H.palavras < 80) && !home.truncado;

  // trecho = frase nominal com artigo, para encaixar em "[achado verificável]" dos scripts.
  const add = (codigo, categoria, severidade, confianca, claim, trecho, evidencia, recomendacao, url = urlHome, metodo = 'GET público + leitura do HTML') => {
    achados.push({
      finding_id: 'f_' + hash(auditId + '|' + codigo + '|' + url), audit_id: auditId, company_id: reg.company_id,
      codigo, category: categoria, claim, trecho, source_url: url, method: metodo, observed_at: observado,
      evidence: recorte(evidencia, 300), confidence: confianca, severity: severidade, recommendation: recomendacao,
      reviewer_status: 'pendente'
    });
  };

  // A. HTTPS, redirecionamentos, canônica.
  if (/^http:/.test(urlHome)) add('SEM_HTTPS', 'tecnico', 'alta', 0.95, 'O site abre sem conexão segura (HTTPS).', 'o site abrindo com o aviso de "não seguro" no navegador', 'URL final da home: ' + urlHome, 'Instalar certificado SSL e redirecionar todo o tráfego para HTTPS.');
  else if (reg.http_inseguro && reg.http_inseguro.status === 200 && !reg.http_inseguro.vai_para_https) add('HTTP_SEM_REDIRECT', 'tecnico', 'media', 0.9, 'A versão http:// do site abre sem redirecionar para a versão segura.', 'a versão sem HTTPS do site abrindo sem redirecionar para a versão segura', 'GET ' + reg.http_inseguro.url + ' → status 200, URL final ' + reg.http_inseguro.url_final, 'Redirecionar (301) todas as URLs http:// para https://.', reg.http_inseguro.url);
  if (!H.canonical) add('CANONICAL_AUSENTE', 'seo', 'baixa', 0.9, 'A página inicial não declara URL canônica.', 'a falta de URL canônica na página inicial', 'Nenhuma tag <link rel="canonical"> no HTML da home.', 'Declarar a URL canônica em todas as páginas.');
  else if (H.canonical.href) {
    let host = '';
    try { host = new URL_(H.canonical.href, urlHome).hostname.replace(/^www\./, ''); } catch (err) { host = ''; }
    if (host && host !== reg.dominio && !host.endsWith('.' + reg.dominio)) add('CANONICAL_OUTRO_DOMINIO', 'seo', 'media', 0.9, 'A URL canônica da página inicial aponta para outro domínio.', 'a URL canônica da página inicial apontando para outro domínio', H.canonical.tag, 'Corrigir a canônica para o próprio domínio.');
  }

  // B. Title, description, títulos, robots, sitemap.
  const marcaNorm = semAcento(e.nome || '');
  if (!H.title) add('TITLE_AUSENTE', 'seo', 'alta', 0.95, 'A página inicial não tem título (tag title).', 'a página inicial sem título para o Google e para a aba do navegador', 'Nenhuma tag <title> no HTML da home.', 'Criar título com especialidade, cidade e marca.');
  else {
    const t = semAcento(H.title);
    if (H.title.length < 15 || /^(home|inicio|pagina inicial|bem[- ]vindo|site|index)$/.test(t)) add('TITLE_GENERICO', 'seo', 'media', 0.85, 'O título da página inicial é curto ou genérico ("' + H.title + '").', 'o título genérico da página inicial ("' + H.title + '")', '<title>' + H.title + '</title>', 'Usar título descritivo com o serviço principal e a cidade.');
    else if (H.title.length > 70) add('TITLE_LONGO', 'seo', 'baixa', 0.85, 'O título da página inicial tem ' + H.title.length + ' caracteres e tende a ser cortado nos resultados de busca.', 'o título longo da página inicial', '<title>' + H.title + '</title>', 'Reduzir o título para até ~60 caracteres.');
    if (e.cidade && !t.includes(semAcento(e.cidade)) && !(H.description && semAcento(H.description.valor).includes(semAcento(e.cidade)))) add('SEM_CIDADE_TITULO', 'local', 'baixa', 0.85, 'Nem o título nem a descrição da página inicial citam a cidade (' + e.cidade + ').', 'o nome da cidade fora do título e da descrição da página inicial', 'Título: "' + H.title + '"; descrição: "' + (H.description ? H.description.valor : '(ausente)') + '"', 'Incluir a cidade no título e na descrição para buscas locais.');
  }
  if (!H.description || !H.description.valor) add('META_DESC_AUSENTE', 'seo', 'media', 0.95, 'A página inicial não tem meta description.', 'a falta do texto de resumo da página inicial que aparece no Google', H.description ? H.description.tag : 'Nenhuma <meta name="description"> no HTML da home.', 'Escrever descrição com oferta, cidade e chamada para agendamento.');
  if (conteudoConfiavel) {
    if (!H.h1.length) add('H1_AUSENTE', 'seo', 'media', 0.9, 'A página inicial não tem título principal (H1).', 'a ausência de título principal (H1) na página inicial', 'Nenhuma tag <h1> no HTML da home (H2 encontrados: ' + H.h2.length + ').', 'Definir um H1 claro com o serviço principal.');
    else if (H.h1.length > 1) add('H1_MULTIPLOS', 'seo', 'baixa', 0.9, 'A página inicial tem ' + H.h1.length + ' títulos H1.', 'os ' + H.h1.length + ' títulos H1 da página inicial', 'H1: ' + H.h1.slice(0, 4).join(' | '), 'Manter um único H1 e usar H2/H3 para seções.');
  }
  const robotsMeta = semAcento((H.robots && H.robots.valor) || '') + ' ' + semAcento(home.x_robots_tag || '');
  if (/noindex/.test(robotsMeta)) add('NOINDEX_HOME', 'seo', 'alta', 0.95, 'A página inicial pede aos buscadores para não ser indexada (noindex).', 'a página inicial marcada como "noindex" (pedido para não aparecer no Google)', H.robots ? H.robots.tag : 'Cabeçalho X-Robots-Tag: ' + home.x_robots_tag, 'Remover o noindex da home e das páginas comerciais.');
  if (reg.sitemap && !reg.sitemap.encontrado) add('SITEMAP_AUSENTE', 'seo', 'baixa', 0.85, 'Não foi encontrado sitemap XML.', 'a falta de sitemap XML', 'GET ' + reg.sitemap.url + ' → status ' + reg.sitemap.status + (reg.robots && reg.robots.encontrado ? '; robots.txt sem linha Sitemap' : '; robots.txt não encontrado'), 'Publicar sitemap.xml e declará-lo no robots.txt.', reg.sitemap.url);

  // C. Páginas comerciais.
  const grupos = new Set(paginasOk.map((p) => p.grupo));
  if (conteudoConfiavel && !grupos.has('servicos') && !H.links.some((l) => RX.servicos.test(semAcento(l.href + ' ' + l.texto)))) add('SEM_PAGINA_SERVICOS', 'conteudo', 'media', 0.75, 'A página inicial não leva a uma página de serviços, tratamentos ou especialidades.', 'a falta de uma página de serviços ou tratamentos ligada à página inicial', 'Nenhum link da home com "tratamento", "serviço", "especialidade", "procedimento" ou "exame" (' + H.links.length + ' links lidos).', 'Criar uma página por serviço principal, com descrição e chamada para agendamento.');

  // D. JSON-LD.
  const sch = tiposSchema(todas.flatMap((x) => x.d.ldjson));
  if (!todas.some((x) => x.d.ldjson.length)) add('SCHEMA_AUSENTE', 'dados_estruturados', 'media', 0.9, 'Nenhuma das páginas analisadas tem dados estruturados (JSON-LD/schema.org).', 'as páginas sem informar ao Google, no formato próprio, os dados da clínica', 'Nenhum <script type="application/ld+json"> em ' + paginasOk.length + ' página(s) lida(s).', 'Adicionar JSON-LD do tipo Dentist/MedicalClinic com nome, endereço, telefone e horário.');
  else if (sch.erros.length) add('SCHEMA_INVALIDO', 'dados_estruturados', 'media', 0.9, 'Há bloco de dados estruturados com erro de sintaxe JSON.', 'um bloco de dados estruturados com erro de sintaxe', 'Trecho: ' + sch.erros[0], 'Corrigir o JSON-LD e validar no Teste de Pesquisa Aprimorada do Google.');
  else if (!sch.tipos.some((t) => TIPOS_LOCAIS.test(t))) add('SCHEMA_SEM_NEGOCIO', 'dados_estruturados', 'baixa', 0.85, 'Os dados estruturados não identificam a clínica como negócio local (tipos: ' + sch.tipos.join(', ') + ').', 'os dados estruturados sem identificar a clínica como negócio local', 'Tipos JSON-LD encontrados: ' + sch.tipos.join(', '), 'Incluir o tipo Dentist/MedicalClinic (LocalBusiness) com NAP completo.');

  // E. Mobile.
  if (!H.viewport) add('VIEWPORT_AUSENTE', 'mobile', 'alta', 0.95, 'A página inicial não tem a configuração de tela para celular (meta viewport).', 'a página inicial sem ajuste para a tela do celular', 'Nenhuma <meta name="viewport"> no HTML da home.', 'Adicionar meta viewport e revisar o layout responsivo.');

  // G. Conteúdo.
  if (conteudoConfiavel && H.palavras < 150) add('CONTEUDO_RASO', 'conteudo', 'media', 0.7, 'A página inicial tem pouco texto legível (cerca de ' + H.palavras + ' palavras).', 'a página inicial com pouco texto sobre os tratamentos', 'Contagem de palavras do texto visível no HTML: ' + H.palavras + '.', 'Explicar serviços, diferenciais, equipe e como agendar.');

  // H. GEO/AEO = prontidão.
  const temFaq = todas.some((x) => RX.faq.test(semAcento(x.d.texto)) || x.d.ldjson.some((b) => /FAQPage/.test(b)));
  if (conteudoConfiavel && !temFaq && !todas.some((x) => x.d.ldjson.length)) add('GEO_PRONTIDAO_BAIXA', 'geo', 'baixa', 0.75, 'As páginas analisadas não têm perguntas frequentes nem dados estruturados, sinais que ajudam buscadores e assistentes de IA a entender o conteúdo (prontidão, não prova de citação).', 'a falta de perguntas frequentes e de dados estruturados para buscadores e assistentes de IA', 'Sem "perguntas frequentes"/FAQ e sem JSON-LD em ' + paginasOk.length + ' página(s).', 'Criar seção de perguntas frequentes por serviço, com marcação FAQPage.');

  // I. Local (NAP) em todas as páginas analisadas.
  const juntar = todas.map((x) => x.d.texto).join(' ');
  const linksTodos = todas.flatMap((x) => x.d.links);
  const telLink = linksTodos.find((l) => /^tel:/i.test(l.href));
  // Botão de WhatsApp aberto por script (href="#", aria-label/classe "whatsapp") também conta (execução 3543, Fahl).
  const waLink = linksTodos.find((l) => RX.whatsapp.test(l.href) || /whatsapp/i.test(l.tag + ' ' + l.texto));
  const waMencao = !waLink && paginasOk.some((p) => /whatsapp|wa\.me/i.test(p.corpo));
  const telTexto = RX.telefone.exec(juntar);
  if (conteudoConfiavel && !telLink && !telTexto && !waLink) add('TELEFONE_NAO_ENCONTRADO', 'local', 'media', 0.75, 'Não encontramos telefone ou WhatsApp publicado nas páginas analisadas.', 'a falta de telefone ou WhatsApp visível no site', 'Sem link tel:, sem link de WhatsApp e sem número no texto de ' + paginasOk.length + ' página(s).', 'Publicar telefone e WhatsApp clicáveis no topo e no rodapé.');
  if (conteudoConfiavel && !RX.cep.test(juntar) && !RX.logradouro.test(juntar)) add('ENDERECO_NAO_ENCONTRADO', 'local', 'media', 0.7, 'Não encontramos endereço publicado nas páginas analisadas.', 'a falta de endereço publicado no site', 'Sem CEP e sem logradouro (rua, avenida…) no texto de ' + paginasOk.length + ' página(s).', 'Publicar endereço completo e mapa na página de contato e no rodapé.');

  // J. Conversão.
  if (conteudoConfiavel) {
    const ctas = [...H.links, ...H.botoes].filter((l) => RX.agendamento.test(semAcento(l.texto + ' ' + (l.href || ''))));
    const agendaExterna = H.iframes.some((s) => RX.agendaExterna.test(s)) || H.links.some((l) => RX.agendaExterna.test(l.href));
    if (!ctas.length && !agendaExterna && !waLink) add('SEM_CTA_AGENDAMENTO', 'conversao', 'alta', 0.8, 'A página inicial não tem botão ou link de agendamento.', 'a ausência de um botão de agendamento na página inicial', 'Nenhum link ou botão da home com "agendar", "marcar", "consulta online" ou "reservar"; sem agenda online incorporada (' + H.links.length + ' links e ' + H.botoes.length + ' botões lidos).', 'Colocar um botão "Agendar consulta" visível no topo e em cada serviço.');
    if (!waLink) add('SEM_LINK_WHATSAPP', 'conversao', 'media', waMencao ? 0.6 : 0.85, 'Nenhuma das páginas analisadas tem link direto para conversar no WhatsApp.', 'a falta de um link direto para o WhatsApp no site', 'Nenhum link wa.me/api.whatsapp.com em ' + paginasOk.length + ' página(s) (' + linksTodos.length + ' links lidos).' + (waMencao ? ' A palavra WhatsApp aparece no código: pode haver botão carregado por script; conferir no navegador.' : ''), 'Adicionar botão de WhatsApp com mensagem inicial pronta.');
    if (!telLink && !waLink && !waMencao && !todas.some((x) => x.d.formularios)) add('SEM_CONTATO_DIRETO', 'conversao', 'alta', 0.85, 'As páginas analisadas não têm formulário, telefone clicável nem link de WhatsApp.', 'a falta de um canal de contato com um clique (formulário, telefone ou WhatsApp)', 'Sem <form>, sem tel: e sem link de WhatsApp em ' + paginasOk.length + ' página(s).', 'Oferecer pelo menos um canal de contato com um clique em todas as páginas.');
  }

  // Principal e resumo (revisão de conversão, 09/10/2026): primeiro o que o dono da clínica entende na hora e afeta
  // agendamento/contato (faixa 1), depois visibilidade compreensível (faixa 2); itens técnicos (faixa 3: schema, canonical,
  // sitemap, H1…) só entram no resumo. Sem faixa 1/2, o decisor recebe o script "Abordagem alternativa" (sem [achado]).
  const FAIXA1 = ['SEM_CTA_AGENDAMENTO', 'SEM_CONTATO_DIRETO', 'SEM_LINK_WHATSAPP', 'TELEFONE_NAO_ENCONTRADO', 'VIEWPORT_AUSENTE'];
  const FAIXA2 = ['NOINDEX_HOME', 'SEM_HTTPS', 'ENDERECO_NAO_ENCONTRADO', 'SEM_PAGINA_SERVICOS', 'TITLE_AUSENTE', 'TITLE_GENERICO', 'SEM_CIDADE_TITULO', 'META_DESC_AUSENTE', 'HTTP_SEM_REDIRECT'];
  const FAIXA3 = ['H1_AUSENTE', 'SCHEMA_AUSENTE', 'SCHEMA_INVALIDO', 'CANONICAL_OUTRO_DOMINIO', 'SITEMAP_AUSENTE', 'SCHEMA_SEM_NEGOCIO', 'H1_MULTIPLOS', 'TITLE_LONGO', 'CANONICAL_AUSENTE', 'CONTEUDO_RASO', 'GEO_PRONTIDAO_BAIXA'];
  const ORDEM = [...FAIXA1, ...FAIXA2, ...FAIXA3];
  const apelo = (c) => (ORDEM.indexOf(c) < 0 ? 99 : ORDEM.indexOf(c));
  const elegiveis = achados.filter((a) => a.confidence >= CONF_MIN_ABORDAGEM).sort((a, b) =>
    apelo(a.codigo) - apelo(b.codigo) || SEV_PESO[b.severity] - SEV_PESO[a.severity] || b.confidence - a.confidence || a.codigo.localeCompare(b.codigo));
  const resumo = [];
  for (const a of elegiveis) if (resumo.length < 3 && !resumo.some((r) => r.category === a.category)) resumo.push(a);
  for (const a of elegiveis) if (resumo.length < 3 && !resumo.includes(a)) resumo.push(a);
  // Gancho comercial: faixa 1 ou 2 de severidade média/alta. Sem ele, um achado técnico médio/alto ainda sustenta a abordagem
  // pelo script alternativo (gancho_tecnico = true). Severidade baixa nunca sustenta sozinha (QA da Fase C).
  const principal = resumo.find((a) => !FAIXA3.includes(a.codigo) && a.severity !== 'baixa') || resumo.find((a) => a.severity !== 'baixa') || null;
  auditoria.gancho_tecnico = !!principal && FAIXA3.includes(principal.codigo);
  auditoria.principal_finding_id = principal ? principal.finding_id : null;
  auditoria.resumo_finding_ids = resumo.map((a) => a.finding_id);
  if (!principal) auditoria.status = 'sem_oportunidade';
  return { auditoria, achados };
}

return $input.all().map((i) => {
  const reg = i.json;
  const { auditoria, achados } = analisar(reg);
  return { json: { company_id: reg.company_id, empresa: reg.empresa, auditoria, achados } };
});

// ATOM2_03 · W05_SCORE_QA · Score v1 + rascunho D1 + fila de QA (Code node, "Run Once for All Items").
