const cfgValor = (k, padrao) => (cfg[k] && cfg[k].status === 'CONFIGURADO' && cfg[k].valor && !/^PENDENTE/i.test(cfg[k].valor) ? cfg[k].valor : padrao);

const VERSAO = cfgValor('SCORE_VERSAO', 'score_v1');
const FAIXA_A = Number(cfgValor('SCORE_FAIXA_A', '75')), FAIXA_B = Number(cfgValor('SCORE_FAIXA_B', '50'));
const verticais = cfgValor('VERTICAIS_PERMITIDAS', 'dental,medical').split(',').map((s) => s.trim()).filter(Boolean);
const cidadesCfg = cfgValor('CIDADES_ALVO', '');
const CONSULTOR = cfgValor('CONSULTOR_NOME', 'Zayra');
const SEV_PONTOS = { alta: 12, media: 7, baixa: 3 };

const texto = (v) => (v === null || v === undefined ? '' : String(v).trim());
const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
function hash(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

