  dental: 'Olá, [Nome]! Identificamos uma oportunidade no site da [Empresa] que pode facilitar novos agendamentos: [achado].\nPreparei um diagnóstico rápido. Posso enviar?',
  medical: 'Olá, [Nome]! Encontramos um ponto de melhoria na jornada de agendamento da [Empresa]: [achado].\nTenho uma análise objetiva, com evidências. Posso compartilhar?',
  tires: 'Olá, [Nome]! Analisamos o site da [Empresa] e encontramos uma oportunidade para facilitar pedidos de orçamento: [achado].\nPosso te mostrar?'
};
// "Abordagem alternativa" (mesma biblioteca): quando só há achado técnico (schema, sitemap, H1…), que não faz sentido para o dono da clínica.
const SCRIPT_ALTERNATIVA = 'Olá, [Nome]! Analisei algumas páginas públicas da [Empresa] e preparei duas sugestões para melhorar a jornada do cliente.\nPosso compartilhar?';
const SCRIPT_RECEPCAO = 'Olá! Tenho um diagnóstico breve do site da [Empresa]. Quem cuida do marketing ou comercial para eu encaminhar?';
// Mensagem ao decisor; sem nome, mantém [Nome] para preencher quando a recepção indicar a pessoa.
function montarMensagem(vertical, empresa, trecho, nomeContato) {
  const modelo = SCRIPTS[vertical];
  if (!modelo || !trecho) return null;
  return modelo.replace('[Nome]', nomeContato || '[Nome]').replace('[Empresa]', empresa).replace('[achado]', trecho);
}
const montarRecepcao = (empresa) => SCRIPT_RECEPCAO.replace('[Empresa]', empresa);

// Lista reaproveitada do ATOM_02 + Playbook (sem promessa de posição, prejuízo, garantia ou números inventados).
// <guarda> — bloco canônico: copiado idêntico para W05, W05b, W07 e W08 por n8n/tools/sync_guarda.js (teste confere).
// Fronteiras Unicode: \b do JavaScript não trata "é", "à" etc. como letra.
const I = '(?<![\\p{L}\\p{N}])', F = '(?![\\p{L}\\p{N}])';
const rx = (corpo) => new RegExp(I + corpo + F, 'iu');
const EXTENSO = '(um|uma|dois|duas|tr[eê]s|quatro|cinco|seis|sete|oito|nove|dez|onze|doze|treze|quatorze|catorze|quinze|dezesseis|dezessete|dezoito|dezenove|vinte|trinta|quarenta|cinquenta|sessenta|setenta|oitenta|noventa|cem|cento|duzentos|duzentas|trezentos|trezentas|quatrocentos|quinhentos|seiscentos|setecentos|oitocentos|novecentos)';
const PRECO_RX = [
  /(R|US|U)?\s*[$＄]\s*\d/i,                                                                   // R$ 3.000, R $3000, US$ 500, $500
  rx('\\d{1,3}([.\\s]\\d{3})+([.,]\\d{2})?'),                                                 // 3.000 / 14.000,00 / 1 500,00
  rx('\\d+([.,]\\d+)?\\s*(mil|reais|k)'),                                                     // 3 mil, 900 reais, 3k
  rx(EXTENSO + '(\\s+e\\s+' + EXTENSO + ')*\\s+(mil|reais)'),                                 // três mil, dois mil e quinhentos
  rx('\\d+,\\d{2}'), rx('\\d+\\.\\d{2}'),                                                     // 500,00 / 500.00
  rx('\\d+([.,]\\d+)?\\s*(/\\s*m[eê]s|por m[eê]s|mensais|ao m[eê]s|/\\s*ano|por ano)'),       // 1500/mês, 990 mensais
  rx('\\d+\\s*x\\s*(de\\s*)?(R\\$\\s*)?\\d+'),                                                 // 12x 300, 2x de 750
  rx('(valor|custo|taxa|or[cç]amento|ticket|plano|investimento)\\s*(:|mensal|anual|de|é|e|fica|sai|total|inicial)?\\s*(R\\$\\s*)?\\d+'), // Valor: 1500, orçamento de 1500
  rx('(?<!(oportunidades|resultados|dados|casos|problemas|ganhos|melhorias|clientes|pacientes|n[uú]meros|exemplos|situa[cç][oõ]es|pessoas|avalia[cç][oõ]es|depoimentos|evid[eê]ncias|mudan[cç]as|benef[ií]cios)\\s)reais'),
  rx('pre[cç]os?'),
  rx('valor(es)?\\s+(de|do|da|para|é|e|fica|sai|total|mensal)'),
  rx('investimento\\s+(de|é|e|fica|sai|total|inicial|mensal)'),
  rx('(mensalidade|parcelas?|parcelado|entrada de|setup de|desconto|à vista|a vista|boleto|pix)'),
  rx('(custa|custo de|cobramos|sai por|fica por|a partir de)')
];
// Promessas e alegações proibidas (handoff §8; scripts de 09/10). "Ninguém pode garantir isso" (script ChatGPT) passa.
const PROIBIDOS = [/primeira posi[cç][aã]o/i, /topo do google/i, /garant(imos|ido|idos|ida|idas|o\b|ia de)/i, /posi[cç][aã]o\s*\d/i, /\b\d+\s*(visitas|clientes|pacientes) (por|ao) m[eê]s/i, /preju[ií]zo/i, /queda de vendas/i, /perdendo (clientes|pacientes|vendas)/i, /cliente oculto/i, /chatgpt (indicou|citou|recomendou)/i];
const bloqueios = (t) => [...PRECO_RX.filter((r) => r.test(String(t || ''))).map(() => 'preço antes da proposta'), ...PROIBIDOS.filter((r) => r.test(String(t || ''))).map((r) => 'termo proibido ' + r.source)];
// </guarda>
// Mensagens e achados passam pela trava completa (preço + termos proibidos): o título do site entra em alguns trechos.
const violacoes = (t) => bloqueios(t);

function pontuar(e, aud, achados) {
  const det = {};
  // Fit (25): vertical 10, região 10, porte 5.
  let regiao, regiaoMotivo;
  if (!cidadesCfg) { regiao = 5; regiaoMotivo = 'CIDADES_ALVO pendente: valor neutro'; }
  else {
    const alvo = cidadesCfg.split(',').map((c) => semAcento(c).trim()).filter(Boolean);
    const ok = alvo.some((c) => c === semAcento(e.cidade) || c === semAcento(e.cidade + '/' + e.uf) || c === semAcento(e.uf));
    regiao = ok ? 10 : 0; regiaoMotivo = ok ? 'cidade no alvo' : 'cidade fora do alvo';
  }
  const unidades = Number(e.unidades) || 0;
  const porte = unidades >= 2 ? 5 : unidades === 1 ? 3 : 2;
  det.fit = { pontos: (verticais.includes(e.vertical) ? 10 : 0) + regiao + porte, max: 25, motivo: [verticais.includes(e.vertical) ? 'vertical permitida' : 'vertical fora do ICP', regiaoMotivo, 'porte: ' + (unidades || 'desconhecido') + ' unidade(s)'].join('; ') };
  // Necessidade demonstrável (35): achados com confiança ≥ 0,7, por severidade.
  const fortes = achados.filter((a) => a.confidence >= 0.7);
  const nec = Math.min(35, fortes.reduce((s, a) => s + SEV_PONTOS[a.severity], 0));
  det.necessidade = { pontos: nec, max: 35, motivo: fortes.length + ' achado(s) candidatos (antes do QA): ' + fortes.map((a) => a.codigo + '/' + a.severity).join(', ') };
  // Capacidade comercial (20): sinais observáveis, sem inventar faturamento.
  const codigos = new Set(achados.map((a) => a.codigo));
  const temCanal = !!(texto(e.telefone) || texto(e.whatsapp)) || !codigos.has('TELEFONE_NAO_ENCONTRADO');
  const cap = 5 + (temCanal ? 5 : 0) + (!codigos.has('SEM_PAGINA_SERVICOS') ? 5 : 0) + (unidades >= 2 ? 5 : 0);
  det.capacidade = { pontos: cap, max: 20, motivo: ['site próprio respondendo', temCanal ? 'canal comercial publicado' : 'sem canal publicado', !codigos.has('SEM_PAGINA_SERVICOS') ? 'páginas de serviço' : 'sem páginas de serviço', unidades >= 2 ? 'várias unidades' : 'uma unidade ou desconhecido'].join('; ') };
  // Canal permitido (10): canal existe 5 + permissão registrada 5.
  const permissao = texto(e.contact_permission_status) === 'autorizado';
  det.canal = { pontos: (temCanal ? 5 : 0) + (permissao ? 5 : 0), max: 10, motivo: (temCanal ? 'canal disponível' : 'sem canal') + '; permissão: ' + (texto(e.contact_permission_status) || 'nao_avaliado') };
  // Qualidade das evidências (10): confiança média dos achados do resumo.
  const resumo = achados.filter((a) => aud.resumo_finding_ids.includes(a.finding_id));
  const media = resumo.length ? resumo.reduce((s, a) => s + a.confidence, 0) / resumo.length : 0;
  det.evidencia = { pontos: Math.round(10 * media), max: 10, motivo: resumo.length ? 'confiança média ' + media.toFixed(2) + ' em ' + resumo.length + ' achado(s) com URL e evidência' : 'sem achado elegível' };
  let total = Object.values(det).reduce((s, d) => s + d.pontos, 0);
  if (e.opt_out === true || texto(e.opt_out) === 'true') { total = 0; det.bloqueio = 'opt_out'; }
  const faixa = total >= FAIXA_A ? 'A' : total >= FAIXA_B ? 'B' : 'C';
  return { total, faixa, det };
}

const agora = new Date().toISOString();
const out = [];
for (const item of $input.all()) {
  const { company_id, empresa: e = {}, auditoria: aud, achados = [] } = item.json;
  const evento = (tipo, motivo, dados) => out.push({ json: { destino: 'evento', evento: { event_id: 'e_' + hash(company_id + '|' + tipo + '|' + aud.audit_id), correlation_id: aud.audit_id, company_id, workflow: 'ATOM2_03', tipo, motivo, dados: JSON.stringify(dados || {}), ocorrido_em: agora } } });

  if (aud.status === 'falha') {
    out.push({ json: { destino: 'auditoria', linha: { ...aud, urls: JSON.stringify(aud.urls), limitacoes: JSON.stringify(aud.limitacoes), resumo_finding_ids: '[]', score: null, faixa: null, score_versao: VERSAO, score_detalhe: '{}', mensagem_d1: null, mensagem_decisor: null, qa_status: 'nao_aplicavel', qa_motivo: 'falha documentada: ' + aud.falha } } });
    out.push({ json: { destino: 'empresa', linha: { company_id, status_motivo: 'N1 falhou: ' + aud.falha, atualizado_em: agora } } });
    evento('N1_FALHA', aud.falha, { limitacoes: aud.limitacoes });
    continue;
  }

  const s = pontuar(e, aud, achados);
  const principal = achados.find((a) => a.finding_id === aud.principal_finding_id) || null;
  const optOut = e.opt_out === true || texto(e.opt_out) === 'true';
  const nomeContato = texto(e.contato_nome);
  const tecnico = aud.gancho_tecnico === true;
  delete aud.gancho_tecnico; // não é coluna de atom2_auditorias
  let decisor = !principal || optOut ? null : tecnico ? SCRIPT_ALTERNATIVA.replace('[Nome]', nomeContato || '[Nome]').replace('[Empresa]', texto(e.nome)) : montarMensagem(e.vertical, texto(e.nome), principal.trecho, nomeContato);
  const problemas = [...violacoes(decisor), ...achados.flatMap((a) => violacoes(a.claim))];
  if (problemas.length) decisor = null;
  // 1º contato: com nome do decisor, a mensagem com achado; sem nome, a recepção (só se houver achado aprovado para depois).
  const mensagem = decisor ? (nomeContato ? decisor : montarRecepcao(texto(e.nome))) : null;
  const qaMotivo = optOut ? 'opt-out: não abordar' : problemas.length ? 'termos proibidos: ' + problemas.join(', ') : !principal ? 'sem oportunidade verificada: não abordar com personalização' : 'revisar achados, a mensagem à recepção e 100% da mensagem ao decisor';

  for (const a of achados) out.push({ json: { destino: 'achado', linha: { ...a, usado_em: aud.resumo_finding_ids.includes(a.finding_id) ? (a.finding_id === aud.principal_finding_id ? 'principal' : 'resumo') : 'apoio' } } });
  out.push({ json: { destino: 'auditoria', linha: { ...aud, urls: JSON.stringify(aud.urls), limitacoes: JSON.stringify(aud.limitacoes), resumo_finding_ids: JSON.stringify(aud.resumo_finding_ids), score: s.total, faixa: s.faixa, score_versao: VERSAO, score_detalhe: JSON.stringify(s.det), mensagem_d1: mensagem, mensagem_decisor: decisor, qa_status: 'pendente', qa_motivo: qaMotivo } } });
  out.push({ json: { destino: 'empresa', linha: { company_id, funil_etapa: 'F2', score: s.total, faixa: s.faixa, score_versao: VERSAO, score_detalhe: JSON.stringify(s.det), status_motivo: aud.status === 'sem_oportunidade' ? 'N1 concluído: sem oportunidade verificada' : 'N1 concluído: aguardando QA', atualizado_em: agora } } });
  evento('N1_CONCLUIDO', aud.status, { achados: achados.length, principal: principal && principal.codigo, score: s.total, faixa: s.faixa });
}
return out;
